// _Gradient Colorful Bubbles

var seed = Math.random() * 1000;
var scale_c, angle,mySize;
let resolution;
let numPoints = 1;
var color1, color2, grad;

let radius = 800;
let numRings;
let t = 0;
let timer = 0;
let filter;

function setup() {
	randomSeed(seed);
	mySize = max(windowWidth, windowHeight);
	createCanvas(mySize, mySize/16*11);
	colorMode(HSB, 360, 100, 100, 100);
	// pixelDensity(5);
	background(0, 0, 95, 100);
	// noFill();
	//fill(0,0,10,10);
	scale_c = int(random(width/2, height));
	resolution = random(10, 20);
	// numRings = 50;
	numRings = int(random(2, 5));

	filter = new makeFilter();
}



function draw() {
	randomSeed(seed);
	let num1 = int(random(int(numRings / 3), int(numRings / 3 * 2)));
	let num2 = int(random(int(numRings / 4), int(numRings / 4 * 2)));
	// let num =int(random(numRings/2));
	// background(0, 0, 95, 100);
	push();
	translate(width / 2, height / 2);
	angle = random(TAU);

	// rotate(angle);
	// translate(scale_c / 2, scale_c / 2);

	let r_plus = int(radius / numRings);

	for (r = 200; r < radius; r += r_plus) {
		for (a = -TAU / numPoints; a < TAU + TAU / numPoints; a += TAU / numPoints) {

			rotate(angle);
			let x = r * cos(a + t);
			let y = r * sin(a + t);
			let n = map(noise(x * resolution, y * resolution), 0, 1, -scale_c, scale_c);
			// gradient color 
			let x_n = random(n);
			let y_n = random(n);
			let angle1 = random(TAU);
	    let angle2 = random(TAU);

			//colorful
			color1 = color(int(360*(angle1/TAU)), 50, 100, 0);
			color2 = color(int(360*(angle1/TAU)), 50, 80, 10);

			//black white
			// color1 = color(0, 0, 80, 0);
			// color2 = color(0, 0, 10, 70);

			fill(0, 100, 100, 50);
			noStroke();
			//strokeWeight(random(0.1, 0.25));
			grad = drawingContext.createRadialGradient(x + random(-x_n,x_n), y + random(-y_n,y_n), 0, x + random(-x_n,x_n), y + random(-y_n,y_n), scale_c);
			grad.addColorStop(0.1, color1);
			grad.addColorStop(1, color2);
			drawingContext.fillStyle = grad;

			// shape
			circle(x + random(-x_n,x_n), y + random(-y_n,y_n), random(scale_c/2,scale_c));

		}
		// endShape(CLOSE);
	}
	pop();
	// angle += TAU / 360;
	timer++;
	image(overAllTexture, 0, 0);
	if (timer == 25) noLoop();
}

function makeFilter() {
	// noiseのフィルターをつくる
	colorMode(HSB, 360, 100, 100, 100);
	drawingContext.shadowColor = color(0, 0, 5, 95);
	overAllTexture = createGraphics(windowWidth, windowHeight);
	overAllTexture.loadPixels();
	for (var i = 0; i < width; i++) {
		for (var j = 0; j < height; j++) {
			overAllTexture.set(
				i,
				j,
				color(
					0,
					0,
					99,
					noise(i / 3, j / 3, (i * j) / 50) * random(5, 15)
				)
			);
		}
	}
	overAllTexture.updatePixels();
}

function keyPressed() {
  //noLoop();
  saveCanvas("GENUARY 2022_0114_Something you’d never make", "png");
}

